{
  "name": "文件通信接口",
  "name_en": "File Communicator",
  "manufacturer": "",
  "description": "用于通过文件、字符设备文件或类 Unix 套接字进行读写通信的软件接口。它常用于把实验仪器暴露为可读写文件节点的场景，以便发送原始字节、读取返回数据并管理基本文件位置与结束符设置。",
  "description_en": "A software communication interface for reading from and writing to files, character device nodes, or Unix-like sockets. It is commonly used when a laboratory instrument is exposed as a readable/writable file endpoint, allowing raw byte exchange and basic management of file position and line termination.",
  "tag_hints": [
    "file I/O communication",
    "character devices",
    "unix socket communication",
    "raw byte read/write",
    "instrument file endpoint"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置通信文件路径",
      "description_en": "Get/set the communication file path."
    },
    {
      "action_name": "auto-close",
      "description": "关闭文件通信连接",
      "description_en": "Close the file communication connection."
    },
    {
      "action_name": "auto-flush_input",
      "description": "刷新内部缓冲区以确保数据已写入",
      "description_en": "Flush the internal buffer to ensure data has been written."
    },
    {
      "action_name": "auto-read_raw",
      "description": "读取原始字节数据",
      "description_en": "Read raw byte data."
    },
    {
      "action_name": "auto-seek",
      "description": "移动文件读写位置",
      "description_en": "Move the file read/write position."
    },
    {
      "action_name": "auto-tell",
      "description": "获取当前文件位置",
      "description_en": "Get the current file position."
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置行终止符",
      "description_en": "Get/set the line terminator."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置超时属性（此接口不支持）",
      "description_en": "Get/set the timeout property (not supported by this interface)."
    },
    {
      "action_name": "auto-write_raw",
      "description": "写入原始字节数据",
      "description_en": "Write raw byte data."
    }
  ]
}

